WITH matched_keys AS (SELECT country, device FROM sessions INTERSECT SELECT country, device FROM sessions WHERE country = 'TH'), reconciled AS (SELECT s.* FROM sessions s JOIN matched_keys k ON s.country = k.country AND s.device = k.device) SELECT DATE_TRUNC('MONTH', started_at) AS activity_month, browser, COUNT_IF(device = 'desktop') AS desktop_events, MAX(started_at) AS ended_at FROM reconciled GROUP BY DATE_TRUNC('MONTH', started_at), browser ORDER BY activity_month ASC
